-- ref_outbox (control; single, cluster)
CREATE TABLE "ref_outbox" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "dedupe_key" TEXT COLLATE BINARY NOT NULL CHECK (length("dedupe_key") <= 128),
  "channel" TEXT COLLATE BINARY NOT NULL CHECK (length("channel") <= 64),
  "state" TEXT COLLATE BINARY NOT NULL DEFAULT 'pending' CHECK (length("state") <= 16),
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "next_at" INTEGER NOT NULL,
  "payload" TEXT NOT NULL CHECK (json_valid("payload")),
  "secret" BLOB,
  "weight" REAL,
  "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)),
  "rule" TEXT COLLATE BINARY CHECK (length("rule") <= 64)
) STRICT;
CREATE UNIQUE INDEX "ref_outbox_dedupe_key_key" ON "ref_outbox" ("dedupe_key");
CREATE INDEX "ref_outbox_due" ON "ref_outbox" ("state", "next_at" DESC) WHERE "state" = 'pending';
CREATE INDEX "ref_outbox_channel_idx" ON "ref_outbox" ("channel") WHERE "weight" IS NOT NULL AND "enabled" = 1;

